create table public.demo_runs (id uuid primary key default gen_random_uuid(), token_hash text not null unique, expires_at timestamptz not null, created_at timestamptz not null default now());
create table public.merchants (id uuid primary key default gen_random_uuid(), run_id uuid not null unique references public.demo_runs(id) on delete cascade, name text not null, created_at timestamptz not null default now());
create table public.bank_accounts (id uuid primary key default gen_random_uuid(), merchant_id uuid not null unique references public.merchants(id) on delete cascade, provider_account_id text not null unique, label text not null, last4 text not null, status text not null default 'PENDING');
create table public.onboarding_sessions (id uuid primary key default gen_random_uuid(), run_id uuid not null references public.demo_runs(id) on delete cascade, token_hash text not null unique, expires_at timestamptz not null, used_at timestamptz);
create table public.conversations (id uuid primary key default gen_random_uuid(), run_id uuid not null references public.demo_runs(id) on delete cascade, actor text not null, step text not null default 'WELCOME', draft jsonb not null default '{}', unique(run_id, actor));
create table public.charges (id uuid primary key default gen_random_uuid(), merchant_id uuid not null references public.merchants(id) on delete cascade, token text not null unique, amount_cents int not null, total_cents int not null, concept text not null, kind text not null, status text not null default 'PENDING', created_at timestamptz not null default now());
create table public.payment_attempts (id uuid primary key default gen_random_uuid(), charge_id uuid not null references public.charges(id) on delete cascade, account_id uuid not null references public.bank_accounts(id) on delete cascade, provider_transaction_id text not null unique, amount_cents int not null, status text not null default 'PENDING', created_at timestamptz not null default now(), expires_at timestamptz not null);
create table public.payments (id uuid primary key default gen_random_uuid(), attempt_id uuid not null unique references public.payment_attempts(id) on delete cascade, provider_transaction_id text not null unique, amount_cents int not null, received_at timestamptz not null default now());
create table public.messages (id uuid primary key default gen_random_uuid(), run_id uuid not null references public.demo_runs(id) on delete cascade, actor text not null, direction text not null, body text not null, actions jsonb not null default '[]', source_id text not null unique, created_at timestamptz not null default clock_timestamp());
create index on public.messages(run_id, created_at);
create table public.webhook_events (id uuid primary key default gen_random_uuid(), provider text not null, external_id text not null, run_id uuid not null references public.demo_runs(id) on delete cascade, type text not null, payload jsonb not null, status text not null default 'PENDING', attempts int not null default 0, last_error text, created_at timestamptz not null default now(), processed_at timestamptz, unique(provider, external_id));
do $$ declare t text; begin
  foreach t in array array['demo_runs','merchants','bank_accounts','onboarding_sessions','conversations','charges','payment_attempts','payments','messages','webhook_events'] loop
    execute format('grant all on public.%I to service_role', t);
    execute format('alter table public.%I enable row level security', t);
  end loop; end $$;